    "id": "parseCityScript",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {
      "label": "Parse City from Description"
    },
    "inputs": {
      "script": "const purpose = $vars.getChannelInfo1.output.purpose;\nconst description = (purpose && purpose.value) ? purpose.value : '';\nconst parts = description.split(',');\nconst city = parts.length >= 3 ? parts[2].trim() : '';\nreturn { city: city, description: description };"
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
